import{_ as e,o as a,c as t,R as o}from"./chunks/framework.4ZHJzgfv.js";const m=JSON.parse('{"title":"Privacy Policy — Outline Manager","description":"Privacy Policy for the Outline Manager iOS app","frontmatter":{"title":"Privacy Policy — Outline Manager","description":"Privacy Policy for the Outline Manager iOS app"},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),i={name:"privacy.md"},r=o('<h1 id="privacy-policy-—-outline-manager" tabindex="-1">Privacy Policy — Outline Manager <a class="header-anchor" href="#privacy-policy-—-outline-manager" aria-label="Permalink to &quot;Privacy Policy — Outline Manager&quot;">​</a></h1><p><em>Last updated: June 28, 2026</em></p><p>Outline Manager (&quot;the App&quot;) is a tool for administering Outline (Shadowsocks) servers that you operate yourself. Your privacy matters, and the App is designed to collect as little as possible.</p><h2 id="data-we-collect" tabindex="-1">Data We Collect <a class="header-anchor" href="#data-we-collect" aria-label="Permalink to &quot;Data We Collect&quot;">​</a></h2><p>We do not collect, transmit, sell, or share any personal data. The App has no user accounts, no analytics, and no third-party tracking or advertising SDKs.</p><h2 id="data-stored-on-your-device" tabindex="-1">Data Stored on Your Device <a class="header-anchor" href="#data-stored-on-your-device" aria-label="Permalink to &quot;Data Stored on Your Device&quot;">​</a></h2><p>The server management configurations you add (server address, secret API path, and certificate fingerprint) are stored only locally on your device, using the system&#39;s standard storage. This information never leaves your device except to communicate directly with the servers you choose to manage.</p><h2 id="network-connections" tabindex="-1">Network Connections <a class="header-anchor" href="#network-connections" aria-label="Permalink to &quot;Network Connections&quot;">​</a></h2><p>The App connects only to the Outline servers you explicitly add. All connections use standard HTTPS/TLS, and the App verifies each server&#39;s self-signed certificate by its SHA-256 fingerprint. No data is sent to us or to any third party.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>The App is not directed to children and collects no data from anyone.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>We may update this policy from time to time. Material changes will be reflected on this page with a new &quot;Last updated&quot; date.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>If you have any questions about this Privacy Policy, contact us at: <a href="mailto:muhammadiy.k@icloud.com" target="_blank" rel="noreferrer">muhammadiy.k@icloud.com</a></p>',15),n=[r];function c(s,l,d,h,p,u){return a(),t("div",null,n)}const v=e(i,[["render",c]]);export{m as __pageData,v as default};
